import {createServer} from 'node:http';
import {readFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
const root='/home/parallels/.codex/worktrees/codex-closeout-main/ngx-compat-material-legacy/';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const cap=JSON.parse(gunzipSync(readFileSync(root+'compatibility/rc/remaining-native-admission-tab-layout-native-css.json.gz')));
for(const member of cap.sources)if(hash(readFileSync(member.path))!==member.sha256)throw Error('Retained Sass source drift '+member.path);
if(hash(cap.compiled_css)!==cap.compiled_css_sha256)throw Error('Retained CSS drift');
const metadata={scope:'Small static native CSS diagnostic only. No Angular component, packed library, compiler/peer floor, browser matrix or G11 qualification.',css_sha256:cap.compiled_css_sha256,
 source_parent:'960d98d87aeac3a24b312cf9112abc6d6383a7fd',source_bindings:['projects/ngx-material-legacy/legacy-tabs/internal/tab-body-base.ts','projects/ngx-material-legacy/legacy-tabs/tab-body.html','projects/ngx-material-legacy/legacy-tabs/tab-body.scss','projects/ngx-material-legacy/legacy-tabs/tab-group.scss'].map(path=>({path,sha256:hash(readFileSync(root+path))})),
 program_sha256:hash(readFileSync('/tmp/ngx-tab-motion-native-css-lab.mjs')),actual_angular_or_packed_qualified:false};
const script=`const metadata=${JSON.stringify(metadata)};
const wait=ms=>new Promise(r=>setTimeout(r,ms));
const frames=()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
document.getElementById('run').addEventListener('click',async()=>{
 const button=document.getElementById('run');button.disabled=true;button.textContent='Running';
 const results=[];
 for(const scenario of [{kind:'depart-left',staged:false},{kind:'depart-left',staged:true},{kind:'origin-left',staged:false},{kind:'origin-left',staged:true},{kind:'origin-right',staged:false},{kind:'origin-right',staged:true}]){
  document.getElementById('lab').innerHTML='<div class="mat-tab-group" style="width:320px"><div class="mat-tab-body-wrapper"><mat-tab-body id="pane" class="mat-tab-body mat-tab-body-active"><div id="content" class="mat-tab-body-content mat-tab-body-content-can-animate" style="transition-duration: 500ms">Pane content</div></mat-tab-body></div></div>';
  await frames();const target=document.getElementById('content'),host=document.getElementById('pane'),events=[],started=performance.now();
  const state=()=>({display:getComputedStyle(target).display,visibility:getComputedStyle(target).visibility,transform:getComputedStyle(target).transform,inline_visibility:target.style.visibility,inline_transform:target.style.transform});
  const before=state();
  for(const type of ['transitionstart','transitionend','transitioncancel'])target.addEventListener(type,e=>events.push({type:e.type,trusted:e.isTrusted,property:e.propertyName,elapsed_ms:e.elapsedTime*1000,at_ms:performance.now()-started,same_target:e.target===target,connected:target.isConnected}));
  host.classList.add('mat-tab-body-animating');
  if(scenario.kind==='depart-left'){
   host.classList.remove('mat-tab-body-active');target.classList.add('mat-tab-body-content-left');target.style.visibility='hidden';
   if(scenario.staged)target.style.removeProperty('visibility');
  }else if(scenario.staged){
   const duration=target.style.transitionDuration,transform=target.style.transform;
   target.style.transitionDuration='0ms';target.style.transform=scenario.kind==='origin-left'?'translate3d(-100%, 0, 0)':'translate3d(100%, 0, 0)';
   target.getBoundingClientRect();target.style.transitionDuration=duration;target.style.transform=transform;
  }
  const after_update=state();await wait(650);results.push({...scenario,before,after_update,after:state(),events});
 }
 document.getElementById('results').textContent=JSON.stringify({...metadata,browser:navigator.userAgent,results},null,2);
 button.textContent='Finished';
});`;
const html='<!doctype html><html><head><meta charset="utf-8"><title>Legacy tab CSS diagnostic</title><style>'+cap.compiled_css+'</style></head><body><h1>Static legacy tab CSS diagnostic</h1><p>No Angular or packed qualification.</p><button id="run">Run six rendering cases</button><div id="lab"></div><pre id="results">Ready</pre><script>'+script+'</script></body></html>';
const server=createServer((req,res)=>{res.setHeader('Content-Type','text/html; charset=utf-8');res.end(html);});
server.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({origin:'http://127.0.0.1:'+server.address().port,pid:process.pid,html_sha256:hash(html)})));
